// 判断是否更大
bool isBetter(double sum, int len, double best_sum, int best_len, int start, int best_start) {
    // sum/len = best_sum / bestLen => sum*best_Len = best_sum * len
    double lhs = sum * best_len;
    double rhs = best_sum * len;
    // 考虑到误差
    if (lhs > rhs + 1e-10) return true;
    if (abs(lhs - rhs) <= 1e-10) {
        if (len < best_len) return true;
        if (len == best_len && start < best_start) return true;
    }
    return false;
}
