package main
​
import (
    "bufio"
    "fmt"
    "math"
    "os"
    "strconv"
)
​
func isBetter(sum float64, len int, bestSum float64, bestLen int, start int, bestStart int) bool {
    // 除法转换乘法
    lhs := sum * float64(bestLen)
    rhs := bestSum * float64(len)
    // 考虑误差
    if lhs > rhs+1e-10 {
        return true
    }
    if math.Abs(lhs-rhs) <= 1e-10 {
        if len < bestLen {
            return true
        }
        if len == bestLen && start < bestStart {
            return true
        }
    }
    return false
}
​
func main() {
    reader := bufio.NewScanner(os.Stdin)
    reader.Scan()
    parts := splitInts(reader.Text())
    N, L := parts[0], parts[1]
​
    nums := make([]float64, N)
    for i := 0; i < N; i++ {
        reader.Scan()
        f, _ := strconv.ParseFloat(reader.Text(), 64)
        nums[i] = math.Log(f) // 转换为对数
    }
​
    prefix := make([]float64, N+1)
    // 前缀和
    for i := 0; i < N; i++ {
        prefix[i+1] = prefix[i] + nums[i]
    }
​
    bestStart := 0
    bestLen := L
    bestSum := prefix[L] - prefix[0]
    // 枚举起点和终点
    for start := 0; start < N; start++ {
        for end := start + L; end <= N; end++ {
            length := end - start
            sum := prefix[end] - prefix[start]
            if isBetter(sum, length, bestSum, bestLen, start, bestStart) {
                bestStart = start
                bestLen = length
                bestSum = sum
            }
        }
    }
​
    fmt.Printf("%d %d\n", bestStart, bestLen)
}
​
func splitInts(s string) []int {
    fields := make([]int, 0)
    for _, part := range splitStr(s) {
        v, _ := strconv.Atoi(part)
        fields = append(fields, v)
    }
    return fields
}
​
func splitStr(s string) []string {
    result := []string{}
    current := ""
    for _, ch := range s {
        if ch == ' ' || ch == '\t' {
            if current != "" {
                result = append(result, current)
                current = ""
            }
        } else {
            current += string(ch)
        }
    }
    if current != "" {
        result = append(result, current)
    }
    return result
}
